    "year": 2019,
    "subject": "Geography",
    "format": "single",
    "stem": "What is common to the places known as Aliyar, Isapur and Kangsabati?",
    "options": [
      "Recently discovered uranium deposits",
      "Tropical rain forests",
      "Underground cave systems",
      "Water reservoirs"
    ],
